import * as THREE from 'three';
import type { CarDef } from '../cars';
import { makeCar, playerPaint } from './car-gen';
import { type CarPaint, rgbOf } from '../../services/paint.service';

/** Player / garage car bodies. Every car is generated by the coachworks (car-gen.ts): no model files to download. */
export class AssetLibrary {
  /** Loading progress for the splash screen. */
  public static total = 0;
  public static done = 0;

  /** A generated catalogue body in the player's paint job (body, accent, livery, wheels, finish). */
  public static genCar(def: CarDef, paint: CarPaint): THREE.Group {
    return makeCar(def.gen, rgbOf(paint.body), undefined, playerPaint(paint.finish), { accent: rgbOf(paint.accent), rim: rgbOf(paint.rim), livery: paint.livery });
  }
  /** Showroom copy of any catalogue car (garage preview). */
  public static async preview(def: CarDef, paint: CarPaint): Promise<THREE.Object3D> { return this.genCar(def, paint); }

  /** Wraps a catalogue car around the physics rig. Returns wheel nodes (FL, FR, RL, RR) for animation. */
  public static async attachPlayerCar(
    root: THREE.Group, def: CarDef, _wheelBase: number, paint: CarPaint
  ): Promise<{ wheels: THREE.Object3D[]; tail: THREE.MeshStandardMaterial | null; spinSign: number; radius: number; holder: THREE.Group; wheelCentreY: number } | null> {
    const car = this.genCar(def, paint), wheels = (car.userData['wheels'] as THREE.Object3D[]).slice(0, 4), radius = (car.userData['size'] as { wr: number }).wr;
    for (const w of wheels) w.rotation.order = 'YXZ';
    const holder = new THREE.Group(); holder.position.y = 0.33 - radius; holder.add(car); holder.name = 'PlayerCarModel'; root.add(holder);
    root.traverse((o) => { const m = o as THREE.Mesh; if (m.isMesh && !holder.getObjectById(m.id)) m.visible = false; });
    return { wheels, tail: null, spinSign: 1, radius, holder, wheelCentreY: radius };
  }
}
